import{_ as s,o as e,c as i,a2 as o}from"./chunks/framework.D66Xq0Kv.js";const u=JSON.parse('{"title":"Operando o Orbit","description":"","frontmatter":{},"headers":[],"relativePath":"pt-BR/guide/operating.md","filePath":"pt-BR/guide/operating.md"}'),t={name:"pt-BR/guide/operating.md"};function r(n,a,d,l,p,c){return e(),i("div",null,[...a[0]||(a[0]=[o(`<h1 id="operando-o-orbit" tabindex="-1">Operando o Orbit <a class="header-anchor" href="#operando-o-orbit" aria-label="Permalink to &quot;Operando o Orbit&quot;">​</a></h1><h2 id="checking" tabindex="-1">Conferindo <a class="header-anchor" href="#checking" aria-label="Permalink to &quot;Conferindo {#checking}&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> orbit</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> status</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                      # administrador, instalação, operações, servidores, agentes, validade dos certificados</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">journalctl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -u</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> orbit</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                 # o plano de controle</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">journalctl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -u</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> orbit-agent</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">           # o agente</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">journalctl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -u</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> k3s</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                      # o Kubernetes</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> k3s</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> kubectl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> get</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pods</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -A</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">           # o que roda no servidor</span></span></code></pre></div><p>O <code>orbit status</code> lê o banco do Orbit em modo somente leitura e funciona com o Orbit rodando.</p><p>O Orbit lê o cluster e aplica seus manifestos pela API do Kubernetes, numa única conexão mantida aberta com as credenciais de administrador que o k3s grava em <code>/etc/rancher/k3s/k3s.yaml</code>, em vez de iniciar um processo <code>kubectl</code> para cada chamada. Comandos executados dentro de containers passam pela mesma API como um stream WebSocket. Logs, rollouts e alguns comandos raros continuam usando o <code>kubectl</code>; a cada 15 minutos, se algum rodou, o Orbit registra no log quantos e de que tipo (<code>kubectl processes started since the last report</code>). Para mandar todas as chamadas de volta ao <code>kubectl</code>, acrescente <code>Environment=ORBIT_KUBE_API=off</code> ao <code>orbit.service</code> com <code>systemctl edit orbit</code> e reinicie o Orbit.</p><h2 id="metrics" tabindex="-1">Métricas <a class="header-anchor" href="#metrics" aria-label="Permalink to &quot;Métricas {#metrics}&quot;">​</a></h2><p>A cada 30 segundos o Orbit coleta amostras de cada servidor e dos workloads que ele roda, e guarda 8 dias de amostras:</p><ul><li><strong>Aplicações:</strong> CPU como fração do limite, a memória da instância mais ocupada, rede de entrada e saída e reinícios com a causa.</li><li><strong>Bancos:</strong> o mesmo, mais o espaço usado no volume e os clientes conectados.</li><li><strong>Servidores:</strong> CPU, memória e disco em uso.</li></ul><p>As páginas mostram o uso atual e gráficos de 1 hora, 24 horas ou 7 dias. Quando o Orbit não conseguiu coletar (estava fora do ar, ou o Kubernetes não respondeu), os gráficos mostram o buraco em vez de uma linha, e a linha do tempo diz por quanto tempo.</p><p>O espaço usado e os clientes conectados de um banco são medidos uma vez por minuto, de dentro dele:</p><ul><li><strong>Um Space não é varrido.</strong> O Garage mantém os bytes e os objetos de cada bucket em contadores e responde a partir deles, então um Space com milhões de arquivos custa o mesmo que um vazio. O número é o que os buckets guardam, sem o espaço que o índice do próprio Garage ocupa no disco.</li><li><strong>Os outros motores percorrem o diretório de dados</strong>, o que é rápido porque um banco mantém poucos arquivos, por mais dados que guarde. Uma varredura que passa de 10 segundos é encerrada onde ela roda. Redis e um PostgreSQL fora do CloudNativePG são a exceção: as imagens deles não têm um jeito seguro de encerrar, então ali a varredura vai até o fim.</li><li><strong>Uma medição que falha</strong> deixa um buraco nesses dois gráficos, nunca um zero, e a página do banco mantém o último tamanho. O Orbit pergunta de novo depois de 1 minuto, depois 2, 4, 8 e daí em diante a cada 15, e volta para uma vez por minuto quando o banco responde. Quando a espera chega a 15 minutos, o log do Orbit tem um aviso <code>database usage not measured</code> com o erro.</li><li><strong>Depois de 15 minutos de medições que falham</strong> o Orbit abre um <a href="./notifications#warnings">aviso</a> para o banco. Ele diz desde quando e o que a última tentativa respondeu, vai para os canais que o acompanham e some na primeira medição. Até lá o aviso de armazenamento desse banco só conhece o último tamanho. O que a última tentativa respondeu diz onde olhar: <ul><li><strong><code>walking the data directory took more than 10 seconds</code>:</strong> a varredura do diretório de dados foi encerrada. Procure um diretório de dados com arquivos demais, ou um disco ocupado ou lento no servidor do banco.</li><li><strong>Nenhuma resposta em 15 segundos, ou um erro do Kubernetes:</strong> o pod não aceita comandos, e a página do banco e os logs dele mostram em que estado ele está. No Redis e num PostgreSQL fora do CloudNativePG, onde a varredura não é encerrada, também pode ser a varredura demorando tudo isso.</li><li><strong>Um erro do banco ou do Garage:</strong> o motor recusou a pergunta, e a mensagem é dele.</li></ul></li><li><strong>Um banco que está sendo criado, restaurado ou em upgrade, ou cujo pod não está rodando, não conta.</strong> Os 15 minutos recomeçam quando ele deveria responder.</li></ul><h2 id="redaction" tabindex="-1">O que os logs nunca guardam <a class="header-anchor" href="#redaction" aria-label="Permalink to &quot;O que os logs nunca guardam {#redaction}&quot;">​</a></h2><p>Toda linha de log, log de operação e detalhe de falha passa pela mesma remoção: credenciais em URLs, tokens bearer e prefixos de tokens conhecidos, valores no estilo <code>password=</code> e <code>token=</code>, segredos em JSON, chaves privadas e tokens do Kubernetes e de registro de agentes.</p><h2 id="backup" tabindex="-1">Backup do Orbit <a class="header-anchor" href="#backup" aria-label="Permalink to &quot;Backup do Orbit {#backup}&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> orbit</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> backup</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --output</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /root/orbit-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">date</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> +%F</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">.tar.gz</span></span></code></pre></div><ul><li>O backup é consistente com o Orbit rodando.</li><li>Ele guarda o banco do Orbit, a autoridade certificadora dos agentes e a chave que sela os segredos. Copie-o para fora do servidor e mantenha-o tão privado quanto o próprio servidor.</li><li>Ele não inclui o estado do Kubernetes nem os dados das suas aplicações: os <a href="./backups">backups dos bancos</a> são separados.</li></ul><p>Para recuperar o plano de controle na mesma máquina:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> systemctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> stop</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> orbit</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> orbit</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> restore</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --input</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /root/orbit-2026-10-09.tar.gz</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> systemctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> start</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> orbit</span></span></code></pre></div><p>O restore recusa enquanto o Orbit responde, recusa arquivos que ele não escreveu e confere a integridade do banco e que ele não é mais novo que o binário. Os arquivos substituídos ficam em <code>/var/lib/orbit/before-restore-&lt;horário&gt;/</code>.</p><h2 id="removing" tabindex="-1">Removendo o Orbit <a class="header-anchor" href="#removing" aria-label="Permalink to &quot;Removendo o Orbit {#removing}&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> systemctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> disable</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --now</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> orbit</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> orbit-agent</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> k3s</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> orbit-firewall</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> orbit-buildkit</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -rf</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /var/lib/orbit</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /var/lib/orbit-agent</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /etc/orbit-agent</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /var/lib/rancher</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /etc/rancher</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /usr/local/lib/orbit</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /var/lib/orbit-buildkit</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  /usr/local/bin/{orbit,orbit-agent,k3s,kubectl,crictl,ctr}</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /etc/systemd/system/{orbit,orbit-agent,k3s,orbit-firewall,orbit-buildkit}.service</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> reboot</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # limpa as interfaces de rede e as regras de firewall que o K3s e o Orbit criaram</span></span></code></pre></div><p>Isso apaga todas as aplicações e bancos do servidor com os seus dados. Backups em armazenamento externo ficam onde estão.</p><h2 id="build-capacity" tabindex="-1">Operação dos builds <a class="header-anchor" href="#build-capacity" aria-label="Permalink to &quot;Operação dos builds {#build-capacity}&quot;">​</a></h2><p>Os controles de <strong>Capacidade de builds</strong> e as evidências do deploy separam tetos configurados, capacidade medida e margens estimadas. Esperar por capacidade não é falha do comando, e a mensagem diz quanto o build precisa e quanto está livre. As reservas das aplicações não seguram os builds; um build só espera por memória, CPU ou disco realmente em uso. Mudar a memória de execução da aplicação não aumenta a memória do build.</p><p>Se a recuperação não consegue confirmar que o executor anterior parou, restaure a conexão do agente. Não apague o registro de admissão nem o cgroup para forçar uma segunda execução. Cgroups vazios de tentativas encerradas permanecem congelados até o reinício do host para impedir trabalho atrasado do containerd. Medições de disco ausentes preservam o último limite de escrita conhecido em membros etcd.</p><p>Para contribuidores, <code>scripts/test-build-capacity-linux.sh</code> executa o cenário em Linux local descartável com BuildKit, containerd e K3s/etcd. Ele registra duração dos builds, latência da aplicação, saúde do plano de controle e evidências reais dos cgroups, sem CI hospedado. O arquivo <code>docs/build-capacity-validation.md</code> no repositório registra o ensaio e os limites dessa validação.</p>`,26)])])}const k=s(t,[["render",r]]);export{u as __pageData,k as default};
